"""Substantive child-specific E0/G0 teaching designs; no historical votes reused."""
import copy
import hashlib
import json
from pathlib import Path

REPO=Path.cwd(); OWN=Path(__file__).resolve().parents[1]
load=lambda p:json.loads(Path(p).read_text())
def write(name,data):
 p=OWN/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');return p
def reference(p):
 p=Path(p);return {'path':p.relative_to(REPO).as_posix(),'sha256':'sha256:'+hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
bi=lambda de,en:{'de':de,'en':en}
ctx=load(OWN/'candidate/author-context.for-material-serialization.json');ids=ctx['newIds']
canonical=load(REPO/ctx['canonical']);goals={g['id']:g for g in canonical['goals']}
case_path=REPO/ctx['correctedCases'];stim_path=REPO/ctx['additionalStimulusCase']
oldcases={c['caseId']:c for c in load(case_path)['cases']};oldcases.update({c['caseId']:c for c in load(stim_path)['cases']})
profiles={p['goalId']:p for p in map(json.loads,(REPO/ctx['originalProfiles']).read_text().splitlines())}
new_cases=[];profile_bodies=[];usage=[]

def expectation(i,ude,uen,pde,pen):
 return {'id':f'e{i}','essentialUnderstandingDe':ude,'essentialUnderstandingEn':uen,'observablePerformanceDe':pde,'observablePerformanceEn':pen}
def derived(key,original,suffix,title,task,performance,focus=None,transfer=False,protocol=None,materials=None):
 c=copy.deepcopy(oldcases[original]);c['caseId']='bcp-'+key+'-'+suffix;c['goalId']=ids[key];c['title']=bi(*title)
 c['authorDerivation']={'wholeOriginalCaseId':original,'wholeOriginalFile':reference(stim_path if original=='lab15-11-c' else case_path),'scope':'New child-specific unreviewed design; no old vote retargeted. Whole original retained.','transferOnly':transfer}
 c['actualTask']=bi(*task);c['expectedReasoningAndSolution']=bi(*performance)
 if protocol:c['protocolAndConditions']=bi(*protocol)
 if materials:c['materialsAndSuppliedData']=bi(*materials)
 if focus:c['childAssessmentBoundary']=bi(*focus)
 c['executionStatus']='not-executed-author-design'
 for f in c.get('futureObservationRecord',{}):c['futureObservationRecord'][f]=None
 c['criterionToObservableRubric']=[]
 new_cases.append(c)
 return c
def profile(key,exps,cs,variation,original_use):
 for c in cs:
  c['criterionToObservableRubric']=[{'expectationId':e['id'],'criterionAndObservable':bi(e['observablePerformanceDe'],e['observablePerformanceEn']),'futureObservation':None,'met':None} for e in exps]
 body={'archetype':'experiment','expectations':exps,'coverageExpectations':{'requiredExpectationIds':[e['id'] for e in exps],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':'independent-changed-condition','textDe':variation[0],'textEn':variation[1]}],'applicationCaseBriefs':[{'id':c['caseId'],'taskDemandDe':c['actualTask']['de']+' Vollständiges Material: '+(OWN/'materials/twenty-complete-child-cases.raw-E0G0.author.json').relative_to(REPO).as_posix()+' #'+c['caseId'], 'taskDemandEn':c['actualTask']['en']+' Complete material: '+(OWN/'materials/twenty-complete-child-cases.raw-E0G0.author.json').relative_to(REPO).as_posix()+' #'+c['caseId'],'expectedPerformanceDe':c['expectedReasoningAndSolution']['de'],'expectedPerformanceEn':c['expectedReasoningAndSolution']['en'],'understandingFocusDe':c.get('childAssessmentBoundary',c['freshIndependentTransfer'])['de'],'understandingFocusEn':c.get('childAssessmentBoundary',c['freshIndependentTransfer'])['en']} for c in cs]}
 profile_bodies.append({'goalId':ids[key],'profile':body,'authorKey':key})
 usage.append({'goalId':ids[key],'wholeSourcesUsed':original_use,'caseIds':[c['caseId'] for c in cs],'reviewAuthority':'none-author-only','newIndependentVotes':0})

k='mixture-composition'
ex=[expectation(1,'Eine Stoffeigenschaft begründet einen Trennschritt; Fraktionen sind noch kein universeller Identitätsnachweis.','A material property justifies a separation step; fractions are not a universal identity test.','Begründet Magnet, Lösen und Filtration für die deklarierte Eisen/Salz/Sand-Probe und kennzeichnet jede Fraktion.','Justifies magnetism, dissolution and filtration for the declared iron/salt/sand sample and labels every fraction.'),expectation(2,'Qualitative Zusammensetzung und Mengenanteil brauchen beobachtete Trennung, nicht bloße Datenlektüre.','Qualitative composition and mass fractions need observed separation rather than data reading.','Führt die Trennung unter Aufsicht selbst aus, trocknet nach freigegebener Methode, tariert und bewahrt eigene Einwaagen und Rückgewinnungsmassen.','Personally separates under supervision, dries by an approved method, tares and retains original input and recovered masses.'),expectation(3,'Rückgewinnungsbilanz und Zusammensetzung sind verschiedene Aussagen; fehlende Masse ist keine neue Stofffraktion.','Recovery balance and composition are different claims; missing mass is not a new constituent.','Berechnet24/30/44% bezogen auf die Ausgangsprobe,98% Rückgewinnung und2% unzugeordnete Differenz; nennt Verlust und Unsicherheit.','Calculates24/30/44% against the original sample,98% recovery and2% unassigned difference; states loss and uncertainty.'),expectation(4,'Eine geänderte Löslichkeit kann den bisherigen analytischen Schluss mehrdeutig machen.','Changed solubility can make the prior analytical conclusion ambiguous.','Entwirft und prüft für einen zusätzlichen löslichen Stoff eine unterscheidende Kontrolle statt den gesamten gelösten Rückstand als NaCl zu etikettieren.','Designs and tests a discriminating control for an added soluble material instead of labelling all dissolved residue NaCl.')]
main=derived(k,'lab15-07-a','a',('Eine Dreikomponentenprobe bilanzieren','Balance a three-component sample'),('Plane und führe die vollständige Trennung einer frisch codierten Eisen/NaCl/Sand-Probe selbst aus; dokumentiere Einwaage, sichere Handgriffe, trockene Fraktionen und Materialbilanz. Werte die getrennt markierten Lehrdaten aus.','Plan and personally separate a fresh coded iron/NaCl/sand sample; record input mass, safe actions, dry fractions and material balance. Separately analyse the labelled practice data.'),('Die Lehrdaten ergeben24% Eisen,30% Salz und44% Sand, zusammen98% Rückgewinnung. Die fehlenden2% sind unzugeordnet und beweisen weder einen vierten Stoff noch Reinheit. Eigene Resultate bleiben offen.','Practice data give24% iron,30% salt and44% sand,98% recovery. Missing2% is unassigned and establishes neither a fourth material nor purity. Original results remain open.'))
transfer=derived(k,'lab15-07-a','b',('Ein weiterer löslicher Stoff verändert die Analyse','Another soluble substance changes the analysis'),('Erst nach dem ersten Ergebnis aufdecken: Eine neue10,00-g-Probe enthält Eisen, Sand, NaCl und Saccharose. Plane ohne Mustertrennweg eine zusätzliche Unterscheidung der gelösten Stoffe. Führe die von der Aufsicht freigegebenen Schritte an einem neuen Ansatz aus und bilanziere nur die tatsächlich getrennt bestimmten Fraktionen.','Reveal after the first result: a new10.00-g sample contains iron, sand, NaCl and sucrose. Independently plan an additional distinction between the dissolved substances. Carry out the supervisor-approved steps on a new batch and balance only fractions actually separately determined.'),('Magnet/Filtration unterscheiden Eisen und Sand; das eingedampfte Filtrat enthält beide löslichen Stoffe. Ein qualitativer Leitfähigkeitsbefund kann Elektrolyt anzeigen, liefert ohne matrixgerechte Kalibrierung aber keine einzelnen Massenanteile. Eine ehrliche gemeinsame lösliche Fraktion mit offener Einzelzuordnung ist besser begründet als erfundene vier exakte Anteile. Die versuchte Methode und deren Grenze müssen praktisch dokumentiert werden.','Magnetism/filtration distinguish iron and sand; evaporated filtrate contains both solutes. Qualitative conductivity can indicate an electrolyte but does not give individual mass fractions without matrix-appropriate calibration. An honestly combined soluble fraction with unresolved individual allocation is justified; four invented exact fractions are not. Actual method and limits must be recorded.'),transfer=True,materials=('Material und sichere Aufsicht wie im ersten Fall; neue deklarierte10,00-g-Mischung aus Eisen, gewaschenem Sand, NaCl und Saccharose, zusätzlich Leitfähigkeitsgerät, Wasserblindprobe sowie einzeln angesetzte NaCl-/Saccharosereferenzen gleicher Probenbeladung. Keine Mengenanteile oder Messergebnisse sind vorgegeben.','Same equipment and supervision as case1; a new declared10.00-g mixture of iron, washed sand, NaCl and sucrose, plus conductivity meter, water blank and separately prepared NaCl/sucrose references at matching sample loading. No fractions or measured outcomes are supplied.'))
profile(k,ex,[main,transfer],('Zusätzlicher löslicher Nicht-Elektrolyt und fehlende quantitative Selektivität.','Added soluble non-electrolyte and missing quantitative selectivity.'),['lab15-07-a complete original + independently specified new four-component batch'])

k='unknown-pure-substance-identity'
ex=[expectation(1,'Eine Identität gilt nur im begründeten Kandidatenraum und braucht unterscheidende Merkmale.','Identity is conditional on a justified candidate set and discriminating traits.','Entwirft einen Entscheidungsweg für NaCl/Saccharose/Sand und begründet die Kombination von Löslichkeit und Leitfähigkeit.','Designs an identification route for NaCl/sucrose/sand and justifies combining solubility and conductivity.'),expectation(2,'Vergleichbare Referenzen benötigen passende Konzentration, Temperatur, Blindwert und unverunreinigte Probe.','Comparable references require matched concentration, temperature, blank and uncontaminated sample.','Setzt0,117g auf20,0mL Gesamtvolumen an, spült die Sonde, misst Referenzen und eigene frische codierte Probe mit Wiederholungen.','Prepares0.117g to20.0mL total volume, rinses the probe and measures references and a fresh coded sample with repeats.'),expectation(3,'Übereinstimmung ist kein analytischer Reinheitsprozentsatz.','Agreement is not an analytical purity percentage.','Ordnet U/V nur im gegebenen Kandidatenraum zu, berechnet9,95mS/cm im Lehrbeispiel und nennt Streuung sowie fehlende Reinheitskalibrierung.','Assigns U/V only within the candidate set, obtains9.95mS/cm in practice data and states spread and missing purity calibration.'),expectation(4,'Ein zusätzlicher Elektrolyt verlangt eine unabhängige selektive Information.','An added electrolyte requires independent selective information.','Wählt und prüft mit Na-/K-Referenzen eine Elementbestimmung; identifiziert innerhalb des deklarierten NaCl/KCl-Raums und begrenzt Aussagen über Anionen oder Mischungen.','Selects and tests elemental analysis against Na/K references; identifies within the declared NaCl/KCl set and limits claims about anions or mixtures.')]
main=derived(k,'lab15-07-b','a',('Eine unbekannte Probe mit passenden Referenzen prüfen','Test an unknown against matched references'),('Führe den selbst begründeten Löslichkeits-/Leitfähigkeitsweg mit einer frisch codierten Reinstoffprobe tatsächlich aus; prüfe Blindwert und Referenzen bei20°C und0,117g/20,0mL Gesamtvolumen. Dokumentiere Rohdaten und entscheide einschließlich Mehrdeutigkeiten.','Personally execute your justified solubility/conductivity route on a fresh coded pure sample; check blank/references at20°C and0.117g/20.0mL total volume. Record raw data and decide including ambiguity.'),(oldcases['lab15-07-b']['expectedReasoningAndSolution']['de'],oldcases['lab15-07-b']['expectedReasoningAndSolution']['en']))
transfer=derived(k,'lab15-07-b','b',('NaCl und KCl durch eine zusätzliche Methode unterscheiden','Distinguish NaCl and KCl using an additional method'),('Erst nach der ersten Antwort: Der neue ausdrücklich reine unbekannte Stoff ist entweder NaCl oder KCl; beide sind löslich und leitfähig. Begründe eine selektive Ergänzung, bereite eigene frische Aliquote und Blind-/Referenzproben vor und miss sie am freigegebenen geschlossenen Element-Emissionsmessplatz nach Geräteeinweisung. Zeichne die eigenen Spektren mit Wellenlängenskala auf, entscheide und prüfe Verschleppung durch eine nachfolgende Blindprobe.','After case1: a new explicitly pure unknown is NaCl or KCl; both dissolve and conduct. Justify a selective additional method, prepare fresh original aliquots and blank/reference samples and measure at an approved enclosed elemental-emission station after device instruction. Retain original wavelength-labelled spectra, decide and check carryover with a subsequent blank.'),('Na- und K-Referenzen liefern unterscheidende Liniensignaturen; die Auswahl erfolgt gegen gemessene Referenzen, nicht allein nach sichtbarer Flammenfarbe. NIST-Orientierung: Na um589,0/589,6nm; K um766,5/769,9nm. Gemischte Signaturen oder kontaminierte Blanks lassen die reine Kandidatenzuordnung offen. Elementnachweis identifiziert im erklärten NaCl/KCl-Raum, weist aber Chlorid oder analytische Reinheit nicht unabhängig nach. Keine Messwerte werden erfunden.','Measured Na and K references provide discriminating line signatures; decide against references rather than visible flame colour alone. NIST orientation: Na near589.0/589.6nm; K near766.5/769.9nm. Mixed signatures or contaminated blanks leave pure-candidate identity unresolved. Elemental evidence identifies within the declared NaCl/KCl set but does not independently establish chloride or analytical purity. No results are invented.'),transfer=True,materials=('Neue sichere NaCl-/KCl-Reinstoffproben, Wasserblindprobe, Waage,20-mL-Messgefäße und jeweils0,100g auf20,0mL Gesamtvolumen. Nur ein an der Schule freigegebener geschlossener Element-Emissionsmessplatz mit geeignetem Na/K-Spektralbereich und aktueller Geräteeinweisung; keine freie Flamme oder Schülerbedienung von Brenngas/Hochspannung. Die Aufsicht betreibt die Anregung; die lernende Person führt unter Einweisung Probenpräparation, freigegebene Probeneingabe und Messaufzeichnung selbst aus. Ohne diesen Messplatz ist dieser Fall noch nicht praktisch durchführbar; vorgegebene Spektren ersetzen die beanspruchte Eigenhandlung nicht.','New safe NaCl/KCl pure samples, water blank, balance,20-mL vessels and0.100g each to20.0mL total volume. Only a school-approved enclosed elemental-emission station with a suitable Na/K spectral range and current instruction; no open flame or learner operation of fuel gas/high voltage. The supervisor operates excitation; the learner personally performs instructed sample preparation, approved input and recording. Without that station this case cannot yet be performed; supplied spectra do not replace the claimed original action.'),protocol=('Vorab Gerätefreigabe und Risikoanweisung; getrennt beschriften, Proben quantitativ ansetzen und Verschleppung vermeiden. Wasserblank, NaCl-Referenz, Blank, KCl-Referenz, Blank, zwei neue unbekannte Aliquote, abschließender Blank; bei Sättigung nur nach gemeinsamer Verdünnung von Probe und Referenzen neu messen, tatsächliche Verdünnung festhalten. Kein Kontakt mit Anregungsquelle; Fehlfunktion sofort Aufsicht melden.','Confirm equipment and risk instruction; label separately, prepare quantitatively and prevent carryover. Water blank, NaCl reference, blank, KCl reference, blank, two new unknown aliquots, final blank; if saturated, remeasure only after matched dilution of sample and references and record actual dilution. No contact with excitation source; report faults to supervisor immediately.'))
profile(k,ex,[main,transfer],('Erweiterter Kandidatenraum erzwingt eine neue selektive Methode; Konzentrationsanpassung und Kontaminationskontrollen bleiben nötig.','An expanded candidate set requires a new selective method; concentration matching and contamination controls remain necessary.'),['Corrected whole lab15-07-b only; original erroneous1.00g recipe excluded','New Na/K emission design; equipment availability openly conditional'])

for k,original,label,transfer_label in [('biotechnological-preparation','lab15-08-a',('Hefe kontrolliert als biologischen Herstellungsweg einsetzen','Use yeast in controlled biological production'),('Den Einsatz von Stärke unabhängig prüfen','Independently test starch as feedstock')),('chemical-preparation','lab15-08-b',('Calciumcarbonat mit einer Stoffmengenbilanz präparieren','Prepare calcium carbonate with a molar balance'),('Eine veränderte limitierende Menge präparativ prüfen','Test a changed limiting quantity in preparation'))]:
 bio=k.startswith('bio');c0=oldcases[original]
 ex=([expectation(1,'Eine biologische Herstellung hängt von aktivem biologischem Material und geeigneten Substraten ab.','Biological production depends on active biological material and suitable substrates.','Plant aktive und inaktivierte Hefe bei gleichen Mengen und30°C und begründet die biologischen Kontrollen.','Plans active and inactive yeast with matched quantities at30°C and justifies biological controls.'),expectation(2,'Die hergestellte Präparation muss tatsächlich gewonnen und aufgearbeitet werden.','The preparation must actually be produced and worked up.','Führt Ansatz, Gasbeobachtung und Filtration sicher ohne Druckaufbau aus; hält eigene Stoffmengen, Zeiten und Verluste fest.','Performs batch preparation, gas observation and filtration safely without pressure build-up; retains original amounts, times and losses.'),expectation(3,'Gasbildung ist kein Nachweis reinen Ethanols und keine vollständige Stoffbilanz.','Gas formation does not identify pure ethanol or establish a complete balance.','Erklärt die Gärungsgleichung als Modell, unterscheidet Hefezellen von gelösten Stoffen und nennt zusätzliche Produktnachweise.','Explains the fermentation equation as a model, distinguishes yeast cells from solutes and states additional product tests.'),expectation(4,'Ein anderes Substrat kann eine Vorbehandlung benötigen; die Kontrolle muss diese von lebender Hefe trennen.','A changed substrate can require pretreatment; controls must separate this from live yeast.','Prüft unabhängig Stärke und eine freigegebene Vorbehandlung gegen Stärke-ohne-Vorbehandlung und Glucosekontrolle.','Independently tests starch and an approved pretreatment against starch without pretreatment and a glucose control.')]
 if bio else [expectation(1,'Reaktionsgleichung und limitierendes Edukt begrenzen die theoretische Produktmasse.','Reaction equation and limiting reactant bound theoretical product mass.','Bilanziert CaCl2/Na2CO3, bestimmt das limitierende Edukt und berechnet die theoretische Masse vor der Herstellung.','Balances CaCl2/Na2CO3, identifies the limiting reactant and calculates theoretical mass before preparation.'),expectation(2,'Fällung, Waschen und Trocknen bestimmen das gewonnene Produkt und seine Verunreinigungen.','Precipitation, washing and drying determine recovered product and contaminants.','Führt Herstellung und kontrollierte Aufarbeitung unter Aufsicht selbst aus und dokumentiert Einwaagen, Waschschritte, Trocknung und Produktmasse.','Personally performs preparation and controlled work-up under supervision, recording quantities, washing, drying and product mass.'),expectation(3,'Ausbeute vergleicht trockene Produktmasse mit der Theorie; sie ist kein Reinheitsnachweis.','Yield compares dry product mass with theory; it is not proof of purity.','Berechnet mit den eigenen Mengen die Ausbeute und erklärt Restfeuchte, gelöste Salze und Verluste als getrennte Grenzen.','Calculates yield from original amounts and explains residual moisture, soluble salts and losses as distinct limits.'),expectation(4,'Eine veränderte Stoffmenge kann das limitierende Edukt wechseln.','A changed quantity can switch the limiting reactant.','Plant und führt einen neuen Ansatz nach selbständiger Mengenprognose aus und prüft eine abweichende Produktmasse ohne erfundene Reinheitsannahme.','Plans and executes a new batch after an independent prediction and examines differing product mass without assuming purity.')])
 main=derived(k,original,'a',label,(c0['actualTask']['de'],c0['actualTask']['en']),(c0['expectedReasoningAndSolution']['de'],c0['expectedReasoningAndSolution']['en']))
