transfer=derived(k,'lab15-11-a','b',('Salz als neuen Faktor bei gleichem Wasserangebot prüfen','Test salinity at equal water availability'),('Nach der ersten Auswertung: Formuliere eine neue Salz-Hypothese und plane unabhängig Kontrolle, Zuteilung und Auswertung. Nutze frische Kressesamen derselben Charge und je drei unabhängige Schalen für Wasser,0,5% und1,0% NaCl. Führe den freigegebenen Vergleich mit gleichem anfänglichem Flüssigkeitsvolumen und gleicher Messdauer tatsächlich aus, dokumentiere zusätzliche Zugaben und bewerte die neue Hypothese.','After case1: formulate a salinity hypothesis and independently plan controls, assignment and analysis. Use fresh cress seeds from one lot and three independent dishes each for water,0.5% and1.0% NaCl. Actually conduct the approved comparison with matched initial liquid volumes/duration, record extra additions and assess the new hypothesis.'),('Gleiche Flüssigkeitsvolumina halten das Angebot vergleichbarer, gleiche Schalen/Samen/Zeit begrenzen Alternativen. Salz kann Keimung unter diesen Bedingungen verändern; die Richtung und Stärke werden erst beobachtet. Ein Trocken/Feucht-Ergebnis sagt keinen Salzschwellenwert voraus. Nicht keimende Samen beweisen ohne weitere Prüfung keinen Tod.','Matched volumes improve comparability; matched dishes, seeds and times constrain alternatives. Salinity may affect germination under these conditions; direction and size remain to be observed. A dry/moist result does not predict a salinity threshold. Non-germination does not establish death without further tests.'),transfer=True,materials=('Kresse, neun gleiche Schalen mit je20 Samen, gleiches Papier; Wasser sowie von der Aufsicht angesetzte0,5%/1,0% w/v NaCl-Lösungen; je5,0mL initial, kein Überfluten.20°C, gleiches Licht,4Tage, tägliche Prüfung; Zugaben mit derselben jeweils zugeteilten Lösung protokollieren. Kein Verzehr oder Wildfang; bei Schimmel geschlossen nach Schulvorgabe entsorgen.','Cress, nine matched dishes with20 seeds each, matched paper; water and supervisor-prepared0.5%/1.0% w/v NaCl solutions;5.0mL initially, no flooding.20°C, matched light,4days with daily checks; record additions using each dish’s allocated solution. No consumption/wild collection; close and dispose under school rules if mould appears.'))
profile(k,ex,[main,transfer],(c0['freshIndependentTransfer']['de'],c0['freshIndependentTransfer']['en']),['Whole11-a; new salinity design retains original safety/own-performance boundary','Whole11-b is not evidence of water requirements'])

k='enzyme-reaction-investigation';c0=oldcases['lab15-03-b']
ex=[expectation(1,'Katalase beschleunigt die Zersetzung von H2O2; ein Roh-Extrakt ist kein gereinigtes Enzym.','Catalase accelerates H2O2 decomposition; crude extract is not purified enzyme.','Erklärt2H2O2→2H2O+O2 und trennt beobachtete Gasbildung von unbewiesener Enzymreinheit oder Gasidentität.','Explains2H2O2→2H2O+O2 and separates gas observation from unproven enzyme purity or gas identity.'),expectation(2,'Vorbehandlung und Messtemperatur sind unterschiedliche Faktoren.','Pretreatment and measurement temperature are different factors.','Vergleicht frischen und von der Aufsicht erhitzten dann auf20°C abgekühlten Extrakt bei sonst gleichen Bedingungen, mit H2O2-ohne-Extrakt und Extrakt-ohne-H2O2.','Compares fresh and supervisor-heated then20°C-cooled extract under matched conditions, with H2O2-without-extract and extract-without-H2O2 blanks.'),expectation(3,'Messregel, Hintergrund und technische Wiederholungen begrenzen den Aktivitätsschluss.','Scoring, background and technical repeats limit the activity inference.','Führt die offene Kleinstmengenreaktion tatsächlich aus, filmt nur Ansätze mit Zeitbezug, dokumentiert drei neue Aliquote je Bedingung und berichtet Blasen/Trübung getrennt.','Actually conducts the small open-vessel reaction, records only time-linked vessels, documents three new aliquots per condition and distinguishes bubbles from turbidity.'),expectation(4,'Ein neuer Einflussfaktor braucht eine eigene Prüfung; Hefegasbildung isoliert keine einzelne Enzymreaktion.','A new factor needs its own test; yeast gas production does not isolate a single enzyme reaction.','Prüft frische Extraktverdünnung bei konstantem Substrat und Gesamtvolumen, unterscheidet bedingte Enzymwirkung von universellem Optimum und lebendem Zellstoffwechsel.','Tests fresh extract dilution at constant substrate and total volume, distinguishing conditional enzyme action from a universal optimum and live-cell metabolism.')]
materials=('Aufsichtslabor, Brille, beschriftete offene kleine Reaktionsgefäße, Pipetten, Uhr,20°C-Wasserbad, frischer Kartoffel-Rohextrakt aus5,0g Kartoffel/20mL Wasser (reiben/filtrieren); von der Aufsicht bereits erhitztes und auf20°C abgekühltes gleiches Aliquot; Wasser und bereitgestellte0,5% H2O2-Lösung. Pro Ansatz2,0mL H2O2+1,0mL Extrakt. Je drei neue Aliquote pro Bedingung; Blank1:2,0mL H2O2+1,0mL Wasser; Blank2:2,0mL Wasser+1,0mL Extrakt. Kamera nur auf Gefäße, keine Personendaten. Keine Resultate vorgegeben.','Supervised laboratory, goggles, labelled small open vessels, pipettes, clock,20°C water bath, fresh crude potato extract from5.0g potato/20mL water (grate/filter); a supervisor-heated and20°C-cooled aliquot of the same extract; water and supplied0.5% H2O2. Each reaction2.0mL H2O2+1.0mL extract. Three fresh aliquots per condition; blank1:2.0mL H2O2+1.0mL water; blank2:2.0mL water+1.0mL extract. Camera only on vessels, no personal data. No outcomes supplied.')
protocol=('Nur unter Aufsicht; Haut/Augenkontakt vermeiden, kein Verzehr und keine druckdichten Gefäße. Alle Reagenzien vor Messung auf20°C bringen. Vorab Hypothese, ausgeloste Reihenfolge und feste30-s-Messregel festlegen:0keine sichtbaren Blasen,1einzelne klar trennbare Blasen,2kontinuierliche Blasenbildung. Keine Schaumhöhe als quantitative Sauerstoffmenge ausgeben; unklare Beobachtung U gesondert markieren. Nach Zugabe Zeit starten, bei30s kodieren; für jede Bedingung drei unbenutzte Aliquote statt wiederholter Substratzugabe. Abfall nach Schulvorgabe.','Supervised only; avoid skin/eye contact, no consumption or pressure-sealed vessels. Equilibrate all reagents to20°C. Predefine hypothesis, randomised order and a30-s scoring rule:0no visible bubbles,1separate clearly resolved bubbles,2continuous bubbling. Do not call foam height quantitative oxygen; record unclear results as U. Start timing at mixing and code at30s; use three unused aliquots per condition, without repeatedly adding substrate. Dispose by school rules.')
main=derived(k,'lab15-03-b','a',('Eine Wärmevorbehandlung von Katalase-Extrakt prüfen','Test heat pretreatment of catalase extract'),('Plane den kontrollierten Frisch/Erhitzt-Vergleich bei gleicher Messtemperatur, führe alle Ansätze selbst offen und sicher aus und bewahre Rohcodes und Abweichungen. Beurteile mit den Blanks, welche Aussage über den Einfluss der Wärmevorbehandlung auf die katalaseassoziierte Reaktion tragfähig ist.','Plan the controlled fresh/heated comparison at matched measurement temperature, actually conduct all open vessels safely and retain raw codes/deviations. Use blanks to assess what heat-pretreatment claim about catalase-associated reaction is justified.'),('Mehr Blasen im frischen als im abgekühlten vorbehandelten Extrakt wäre mit einer Wärmebeeinflussung katalaseassoziierter Aktivität vereinbar; reale Ergebnisse sind offen. Gleiche Messtemperatur verhindert Verwechslung mit bloß schnellerer momentaner Reaktion. Blanks prüfen Eigenblasen und nichtenzymatischen Hintergrund. Das ordinale Ergebnis ist keine O2-Menge, kein kcat und kein universal gültiges Temperaturoptimum; Roh-Extrakt und andere Bestandteile begrenzen die molekulare Ursachenbehauptung.','More bubbling in fresh than cooled pretreated extract would be compatible with heat affecting catalase-associated activity; outcomes remain open. Equal measurement temperature prevents confusing this with a faster current reaction. Blanks test intrinsic bubbles and nonenzymatic background. Ordinal scores are not O2 quantity, kcat or a universal temperature optimum; crude extract and its components limit molecular causal claims.'),materials=materials,protocol=protocol,focus=('Aus dem ganzen Portfolio03-b wird nur die Enzymstation verwendet; Gelherstellung und Mikroskopie werden hier nicht beurteilt.11-b bleibt ein vollständiger zusätzlicher Systemfall, belegt aber ohne isolierte Kontrollen keine einzelne Enzymreaktion.','Only the enzyme station of whole portfolio03-b is used; gel preparation and microscopy are not assessed here. Whole11-b remains an additional system case but cannot isolate one enzyme reaction without further controls.'))
transfer=derived(k,'lab15-03-b','b',('Extraktmenge als unabhängigen neuen Faktor untersuchen','Investigate extract amount as a new independent factor'),('Nach Abschluss des Wärmevergleichs: Entwickle ohne Musterlösung eine neue Hypothese zur Extraktmenge. Prüfe an frischem Extrakt einer neuen Kartoffelcharge drei Stufen bei konstantem H2O2-Angebot und Gesamtvolumen. Lege Kontrollen, Reihenfolge und Auswertung selbst fest; führe die freigegebene Untersuchung tatsächlich aus und vergleiche ihre Aussage mit dem Wärmeversuch.','After the heat comparison independently develop a new hypothesis about extract amount. Use fresh extract from a new potato batch to test three levels at constant H2O2 quantity and total volume. Independently define controls/order/analysis, actually conduct the approved test and compare its inference with the heat experiment.'),('Extraktmengen0/0,5/1,0mL bei festem Gesamtvolumen3,0mL und jeweils2,0mL0,5% H2O2 ändern die Menge katalasehaltigen Rohmaterials, nicht die anfängliche H2O2-Konzentration. Eine linear verdoppelte Wirkung darf nicht vorausgesetzt werden; ordinale Sättigung und unbekannte Extraktzusammensetzung begrenzen das Ergebnis. Bei Eigenschäumen müssen Ansätze ohne H2O2 helfen, sichtbare Artefakte von einer Reaktion zu trennen. Ein gelungenes Wärmeexperiment ersetzt die neue Beobachtung nicht.','Extract amounts0/0.5/1.0mL at3.0mL total volume and fixed2.0mL0.5% H2O2 change crude catalase-bearing material, not initial H2O2 concentration. Do not assume doubled linear effect; ordinal saturation and unknown crude composition limit interpretation. No-H2O2 blanks help distinguish inherent foam from reaction. A successful heat experiment does not replace fresh observations.'),transfer=True,materials=(materials[0]+' Neuer Extrakt derselben Herstellungsart aus einer zweiten Kartoffelcharge; Ansätze2,0mL H2O2 plus0/0,5/1,0mL Extrakt, Wasser jeweils auf3,0mL; je drei neue Aliquote. Alle bei20°C.',''+materials[1]+' New extract prepared in the same way from a second potato batch;2.0mL H2O2 plus0/0.5/1.0mL extract, water to3.0mL total, three new aliquots each, all20°C.'),protocol=protocol)
profile(k,ex,[main,transfer],('Wärmevorbehandlung→Extraktmenge: neue Ursache bei konstantem Substrat; Roh-Extrakt, ordinale Messung und Blanks begrenzen die Erklärung.','Heat pretreatment→extract amount: new cause at constant substrate; crude extract, ordinal scoring and blanks limit explanation.'),['Whole03-b enzyme component adapted into two fully specified direct-reaction designs','Whole11-b retained as contextual systems case only; not credited as isolated-enzyme proof'])

k='organism-stimulus-response';c0=oldcases['lab15-11-c']
ex=[expectation(1,'Eine Reizantwort wird gegen einen definierten Scheinreiz und einen zeitlich gebundenen Ausgangszustand geprüft.','A stimulus response is tested against a defined sham and time-linked baseline.','Begründet Hypothese, Kontakt/Scheinbehandlung, Pflanzenpaarung, Zufallszuteilung und ursprüngliche Messregel des ganzen Mimosa-Designs.','Justifies hypothesis, touch/sham, plant matching, random assignment and the whole Mimosa design’s scoring rule.'),expectation(2,'Schonende Eigenhandlung und Abbruchgrenzen sind Teil des Experiments.','Careful original performance and stop rules are part of the experiment.','Führt nur die im ganzen Design erlaubte sanfte Kontakt-/Scheinhandlung aus, hält Schutz- und Abbruchregeln ein und ersetzt keine ausgefallenen Pflanzen heimlich.','Performs only the whole design’s permitted gentle touch/sham actions, follows protection/stop rules and does not secretly replace failed plants.'),expectation(3,'Pflanzen sind Replikate, Blattpaare sind abhängige Messungen innerhalb einer Pflanze.','Plants are replicates; leaflet pairs are dependent observations within a plant.','Dokumentiert eigene N/C/U-Rohdaten und Zeitbezug, berichtet n=3Pflanzen pro Bedingung und wertet auch Null-/Scheinreaktionen aus.','Records original N/C/U data/timecodes, reports n=3plants per condition and analyses absent/sham responses.'),expectation(4,'Bewegung belegt keine bestimmte zelluläre Ursache; Handhabung kann den Reizvergleich verfälschen.','Movement does not establish a cellular cause; handling can confound the stimulus comparison.','Prüft unabhängig den neuen Topfbewegungsfaktor an sechs vorher nicht gereizten Pflanzen und begrenzt Schlussfolgerungen ohne Schmerz-/Lern-/Ionenkanalbehauptung.','Independently tests the new pot-movement factor with six unstimulated plants and limits conclusions without pain/learning/ion-channel claims.')]
main=derived(k,'lab15-11-c','a',('Eine schonende Kontaktantwort an Mimosa prüfen','Test gentle-touch responsiveness in Mimosa'),(c0['actualTask']['de'].split('Plane und führe anschließend')[0]+' Nutze in diesem ersten Fall nur die sechs Hauptversuchspflanzen. Der neue Handhabungsfaktor wird erst im zweiten Fall aufgedeckt und mit den sechs separaten Transferpflanzen untersucht.',c0['actualTask']['en'].split('Then independently plan')[0]+' Use only the six main-comparison plants in this first case. Reveal the new handling factor only in case2 and investigate it with the six separate transfer plants.'),(c0['expectedReasoningAndSolution']['de'],c0['expectedReasoningAndSolution']['en']),focus=('Das ganze ursprüngliche12-Pflanzen-Design bleibt erhalten: sechs Pflanzen im Hauptvergleich, sechs andere im erst anschließend aufgedeckten Transfer; keine erneute Reizung derselben Pflanzen als unabhängige Leistung.','Retain the whole original12-plant design: six plants in the main comparison and six others in the transfer revealed afterward; repeated stimulation of the same plants is not an independent performance.'))
transfer=derived(k,'lab15-11-c','b',('Topfbewegung als neuen Reiz unabhängig untersuchen','Independently investigate pot movement as a new stimulus'),(c0['freshIndependentTransfer']['de'],c0['freshIndependentTransfer']['en']),(c0['freshTransferExpectedReasoning']['de'],c0['freshTransferExpectedReasoning']['en']),transfer=True,focus=('Nur die sechs im ganzen Design reservierten, vorher nicht gereizten Transferpflanzen verwenden. Die sichere Bewegungsgrenze des ganzen Falles bleibt bindend; keine zusätzliche Kontaktserie.','Use only the six originally reserved and unstimulated transfer plants. Retain the whole case’s safe movement limit; no extra touch series.'))
profile(k,ex,[main,transfer],(c0['freshIndependentTransfer']['de'],c0['freshIndependentTransfer']['en']),['Whole new11-c with original safe contact/sham and separate-six-plant transfer, not executed','11-a/b do not demonstrate stimulus responsiveness'])

# Ecology: whole projects remain available, but each new competence has its own task/output.
ecology=[
 ('organism-identification',('Lebewesen am Schulrasen mit Literatur bestimmen','Identify school-lawn organisms with literature'),('Lebewesen am Gewässerrand mit Literatur bestimmen','Identify pond-edge organisms with literature'),
 [('Beobachtete Merkmale und Bestimmungsliteratur begrenzen die erreichbare taxonomische Auflösung.','Observed traits and identification literature limit taxonomic resolution.','Dokumentiert Merkmale, verwendete Literaturstelle, Entscheidungen und Unsicherheit an tatsächlich beobachteten Organismen.','Records traits, literature entry, identification decisions and uncertainty for organisms actually observed.'),('Ein Übungsgruppenschlüssel ist kein Ersatz für geeignete regionale Bestimmungsliteratur.','A practice grouping key does not replace suitable regional identification literature.','Prüft Gras/Klee/Löwenzahngruppe beziehungsweise Wasserlinsen-/Algenverdacht gegen einen passenden regionalen Führer und belässt offene Fälle offen.','Checks grass/clover/dandelion grouping or duckweed/algal suspicion against a suitable regional guide and retains unresolved cases.'),('Schonende Feldbestimmung verlangt keine Entnahme geschützter Organismen.','Careful field identification does not require collecting protected organisms.','Bestimmt vor Ort vom erlaubten sicheren Weg, dokumentiert nur Organismen und hält Natur-/Artenschutz ein.','Identifies in place from a permitted safe path, records only organisms and observes nature/species protection.'),('Ein neuer Lebensraum kann andere Merkmale und Literatur verlangen.','A changed habitat may require other traits and literature.','Passt den Bestimmungsweg an den zweiten Lebensraum an und unterscheidet Gruppenhäufigkeit von Artenzahl.','Adapts the identification route to the second habitat and distinguishes group frequency from species richness.')],
 ('Führe nur die literaturgestützte Bestimmung der tatsächlich beobachteten Rasenpflanzen aus. Bewahre Merkmalsnotizen, eigene Skizzen/Fotos ohne Personendaten, genaue Literaturstelle und den Entscheidungspfad. Benenne bei unzureichenden Merkmalen die begründete Gruppe statt eine Art zu erfinden.','Perform only literature-based identification of actually observed lawn plants. Retain trait notes, original sketches/photos without personal data, precise literature entry and decision route. State a justified group if species traits are insufficient.'),
 ('Führe unabhängig eine neue literaturgestützte Bestimmung am erlaubten sicheren Gewässerrand aus. Wähle passende Literatur und erkläre, ob sichtbare Merkmale für Wasserlinsengruppe, sicheren Artname oder nur unbestimmten Algenverdacht reichen. Kein Betreten des Wassers oder Wildentnahme.','Independently identify organisms at a permitted safe pond edge with suitable literature. Explain whether visible traits support duckweed group, a secure species name or only unconfirmed algae. Do not enter water or collect wild organisms.'),
 ('Bestimmung ist eine begründete Merkmalszuordnung mit benannter Auflösung; drei Gruppen sind nicht automatisch drei Arten. Ein Algenverdacht bleibt ohne die nötigen mikroskopischen Merkmale unbestimmt. Bestimmungsfehler dürfen nicht durch frei erfundene Artnamen verdeckt werden.','Identification is an argued trait assignment at a stated resolution; three groups do not automatically mean three species. Algal suspicion remains uncertain without necessary microscopic traits. Do not conceal uncertainty by inventing species names.')),
 ('community-site-field-investigation',('Rasengemeinschaften und Standortfaktoren erheben','Survey lawn communities and site factors'),('Gewässerrandgemeinschaften und Standortfaktoren erheben','Survey pond-edge communities and site factors'),
 [('Eine Hypothese bestimmt vergleichbare Stichproben und Messgrößen.','A hypothesis determines comparable samples and outcomes.','Legt vorab Zähl-/Deckungsregel, zufällige Sichtflächen, gleiche Flächengröße und zeitnahe abiotische Messung fest.','Predefines count/cover criteria, randomised observation areas, matched area and contemporaneous abiotic measurements.'),('Originaldaten brauchen Ort, Fläche, Einheit, Methode und Unsicherheit.','Original data need site, area, unit, method and uncertainty.','Erhebt selbst je drei sichere Stichproben pro Standort mit Licht/Feuchte/Temperatur und bewahrt Rohdaten einschließlich unbestimmter Gruppen.','Personally records three safe samples per site with light/moisture/temperature and retains raw data including unknown groups.'),('Zustand, Flächendichte, relative Indizes und Artenzahl sind unterschiedliche Größen.','Standing state, density, relative indices and species richness are different quantities.','Rechnet48/32Grasgruppen-Einheiten pro m² beziehungsweise20/6,7% Deckung korrekt und erklärt den Feuchteindex ohne Prozentwasserbehauptung.','Correctly calculates48/32grass-group units per m² or20/6.7% cover and explains the moisture index without calling it percent water.'),('Ein Standortzusammenhang zeigt ohne Intervention keine alleinige Umweltursache.','A site association does not establish a single environmental cause without intervention.','Nennt Licht/Feuchte/Temperatur/Betritt als mögliche Mitursachen und entwickelt für den zweiten Lebensraum eine neue faire Beprobung.','States light/moisture/temperature/trampling as possible covariates and develops fair new sampling for the second habitat.')],
 ('Plane eine eigene Hypothese zum Vergleich der beiden erlaubten Schulrasenflächen. Führe nur die schonende Freilandaufnahme mit je drei zufälligen0,25-m²-Rahmen und zugehörigen Standortmessungen tatsächlich aus. Dokumentiere die vorab festgelegte Zähleinheit und bekannte Bestimmungsgrenzen; charakterisiere die Gemeinschaft qualitativ und quantitativ.','Plan a hypothesis comparing the two permitted school lawns. Personally conduct only careful field sampling with three random0.25-m² quadrats per site and site measurements. Record the predefined counting unit and identification limits; characterise the community qualitatively and quantitatively.'),
 ('Übertrage die Freilandmethode unabhängig auf zwei sichere Gewässerrandstellen. Lege vor der Erhebung gleiche Sichtfenster, Deckungsschätzung und Zeit-/Licht-/Temperaturbedingungen fest. Erhebe eigene Gemeinschafts- und Standortdaten; gib keine Labor-Vermehrungsrate aus Freilanddeckung aus.','Independently adapt field sampling to two safe pond-edge sites. Predefine matched observation windows, cover estimation and time/light/temperature conditions. Collect original community/site data; do not call field cover a laboratory multiplication rate.'),
 ('Rasen-Lehrdaten:12/0,25=48 und8/0,25=32 pro m²; klonale Pflanzen erschweren Individuenzählung. Gewässerrand-Lehrdaten:20% versus20/3≈6,7% Deckung. Dies sind Bestandsbeschreibungen mit variierenden Standortbedingungen; keine kausale Ein-Faktor-Prüfung oder Vermehrungsrate. Die eigenen Messwerte bleiben offen.','Lawn practice data:12/0.25=48 and8/0.25=32 per m²; clonal plants complicate individual counts. Pond-edge practice data:20% versus20/3≈6.7% cover. These describe standing communities with covarying conditions, not a causal single-factor test or multiplication rate. Original values remain open.')),
 ('controlled-environment-habitat-investigation',('Feuchtewirkung auf Kresse und begrenzte Standorteignung prüfen','Test moisture effects on cress and bounded habitat suitability'),('Lichtwirkung auf Wasserlinsen und begrenzte Standorteignung prüfen','Test light effects on duckweed and bounded habitat suitability'),
 [('Ein kontrollierter Umweltversuch prüft einen Faktor mit artbezogener Messgröße.','A controlled environmental experiment tests one factor with a species-specific outcome.','Formuliert vorab Hypothese, Messgröße Keimanteil/Sprossvermehrung und Gegenkontrolle.','Predefines hypothesis, germination/frond-multiplication outcome and matched control.'),('Tatsächliche Manipulation und Schutzmaßnahmen gehören zum Kompetenznachweis.','Actual manipulation and protection measures belong to competence evidence.','Führt getrennte frische kontrollierte Kresse-/kommerziell bezogene Wasserlinsenansätze ohne Wildentnahme, Verzehr, Schimmelzüchtung oder Freisetzung durch.','Actually conducts separate fresh controlled cress/commercial-duckweed experiments without wild collection, consumption, mould culturing or release.'),('Replikate und konstante Mitfaktoren begrenzen die kausale Aussage.','Replicates and constant covariates bound causal inference.','Dokumentiert pro Ansatz Originalzahlen, Wasser/Volumen, Licht, Temperatur, Zeit und Abweichungen; zählt Gefäße als Replikate.','Records original counts, water/volume, light, temperature, time and deviations by batch; treats vessels as replicates.'),('Lebensraumeignung ist art-, bedingungs- und messgrößenspezifisch.','Habitat suitability is specific to species, conditions and outcome.','Verknüpft die eigene Wirkungsprüfung mit einem begrenzten Eignungsurteil und überträgt Kresse nicht auf alle Rasenarten oder Deckung auf Wachstum.','Links original effect testing to a bounded suitability judgement without generalising cress to all lawn species or cover to growth.')],
 ('Führe ausschließlich den getrennten kontrollierten Kresse-Feuchteversuch durch: gleiche Charge, je drei Schalen mit20 Samen und klar protokollierter niedriger/höherer Wasserzugabe, sonst20°C und gleiches Licht. Lege Wasserzugaben mit der Aufsicht vorab so fest, dass das Papier feucht, aber nicht überflutet ist; vier Tage und Keimkriterium≥2mm. Dokumentiere eigene Daten und begründe ein Eignungsurteil nur für Kresse unter diesen Bedingungen.','Perform only the separate controlled cress-moisture experiment: one seed lot, three20-seed dishes each at recorded lower/higher water addition, otherwise20°C and matched light. Agree amounts with the supervisor beforehand so paper remains moist without flooding; four days, germination criterion≥2mm. Record original data and justify suitability only for cress under these conditions.'),
 ('Prüfe unabhängig Licht statt Feuchte an kommerziell bezogener Wasserlinse: je drei neue Gefäße mit10 Sprossgliedern pro Lichtstufe, gleiche20°C, definierte gleiche Nährlösung/Volumen und7Tage. Lege Zählregel, Zuteilung, Positionstausch und Schutzmaßnahmen selbst fest, erhebe täglich eigene Daten und urteile nur über die untersuchte Population und Lichtspanne.','Independently test light instead of moisture with commercial duckweed: three new vessels with10fronds per light level, matched20°C, defined equal nutrient solution/volume and7days. Independently define scoring, assignment, position rotation and protection, collect daily original counts and judge only the population/light range tested.'),
 ('Ein sauber kontrollierter Kressevergleich kann eine Feuchtewirkung auf Keimung dieser Art stützen; er erklärt nicht allein die ganze Rasenverteilung. Ein kontrollierter Wasserlinsenversuch kann Lichtwirkung auf Sprossvermehrung der verwendeten Population prüfen; Freilanddeckung ist dafür kein Ersatz. Andere Umweltfaktoren und Arten begrenzen jedes Habitaturteil. Nichtwirkung oder widersprüchliche Daten werden ehrlich ausgewertet.','A well-controlled cress comparison may support moisture effects on that species’ germination, without explaining all lawn distribution. Controlled duckweed work may test light effects on frond multiplication of the population used; field cover is no substitute. Other factors/species bound each habitat judgement. Null or conflicting data must be analysed honestly.')),
]
for k,title1,title2,expectations,task1,task2,perf in ecology:
 ex=[expectation(i+1,*s) for i,s in enumerate(expectations)]
 cs=[]
 for original,suffix,title,task in [('lab15-14-a','a',title1,task1),('lab15-14-b','b',title2,task2)]:
  c0=oldcases[original]
  protocol=(task[0]+' Schutzregeln und Materialbedingungen des vollständig gebundenen Ursprungsfalls gelten weiter. Andere Teilvorhaben dieses Projektmaterials liefern Kontext, werden für dieses Kind aber nicht als erledigte Kompetenz gezählt. Lösungen und Rubrik bis nach der eigenen Antwort zurückhalten.',task[1]+' Retain the whole original case’s safety and material conditions. Other subprojects supply context but are not credited as completed competence for this child. Withhold solution and rubric until after the independent response.')
  c=derived(k,original,suffix,title,task,perf,protocol=protocol,transfer=suffix=='b',focus=('Eigenständiges Ergebnis: '+goals[ids[k]]['title']+'. Die beiden anderen ökologischen Kinder brauchen ihre eigenen Handlungen und Ergebnisse.','Independent outcome: '+goals[ids[k]]['titleEn']+'. The other two ecological children need their own actions and outcomes.'))
  cs.append(c)
 profile(k,ex,cs,('Wechsel von Schulrasen zu Gewässerrand bzw. Kresse zu Wasserlinse; passende Literatur, Beprobung und kausale Grenzen neu begründen.','Change from lawn to pond edge or cress to duckweed; justify suitable literature, sampling and causal limits anew.'),['Whole14-a and14-b retained; only child-specific practical output is credited','Original companion tasks remain in the whole universe and are not silently dropped'])

assert len(new_cases)==20 and len(profile_bodies)==10
casefile=write('materials/twenty-complete-child-cases.raw-E0G0.author.json',{'schemaVersion':1,'contentLicense':'CC-BY-4.0','authority':'unreviewed-author-design-only','evidenceLevel':'E0','maximumClaimScope':'G0','cases':new_cases,'actualExecution':False,'independentReviews':0})
